1	/**
2	 * `argparse.HelpFormatter`: usage lines, the options section, and the wrapping
3	 * rules both of them obey.
4	 */
5	
6	import { terminalColumns } from './terminal.mjs';
7	
8	const INDENT_INCREMENT = 2;
9	const MAX_HELP_POSITION = 24;
10	const USAGE_PREFIX = 'usage: ';
11	
12	/**
13	 * `HelpFormatter._format_usage`'s part splitter: bracketed or parenthesised
14	 * groups stay together, everything else splits on whitespace.
15	 */
16	const PART_PATTERN = /\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g;
17	
18	function splitUsageParts(text) {
19	  return text.match(PART_PATTERN) ?? [];
20	}
21	
22	/**
23	 * `HelpFormatter.format_help`: collapse runs of blank lines and leave exactly
24	 * one trailing newline.
25	 */
26	export function normaliseHelp(text) {
27	  return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
28	}
29	
30	/** Greedy word wrap, equivalent to `textwrap.wrap` for help strings. */
31	function wrapText(text, width) {
32	  const words = text.replace(/[\t\n\x0b\f\r ]+/g, ' ').trim().split(' ').filter(Boolean);
33	  if (words.length === 0) return [];
34	  const lines = [];
35	  let current = words[0];
36	  for (const word of words.slice(1)) {
37	    if (current.length + 1 + word.length <= width) {
38	      current += ` ${word}`;
39	    } else {
40	      lines.push(current);
41	      current = word;
42	    }
43	  }
44	  lines.push(current);
45	  return lines;
46	}
47	
48	/** `[-h]` for a flag, `--a A` for a store action, brackets when optional. */
49	export function formatActionUsage(action) {
50	  const optionString = action.optionStrings[0];
51	  const body = action.takesValue ? `${optionString} ${action.metavar}` : optionString;
52	  return action.required ? body : `[${body}]`;
53	}
54	
55	/** `-h, --help` / `--a A`: how an action is announced in the options list. */
56	export function formatActionInvocation(action) {
57	  if (!action.takesValue) return action.optionStrings.join(', ');
58	  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
59	}
60	
61	export class HelpFormatter {
62	  /** @param {string} prog program name shown in the usage line */
63	  constructor(prog) {
64	    this.prog = prog;
65	    this.width = terminalColumns() - 2;
66	  }
67	
68	  /** `_format_usage`, including the two wrapping strategies argparse uses. */
69	  formatUsage(actions) {
70	    const prefix = USAGE_PREFIX;
71	    const optionals = actions.map(formatActionUsage).join(' ');
72	    let usage = [this.prog, optionals].filter((piece) => piece.length > 0).join(' ');
73	    const textWidth = this.width;
74	
75	    if (prefix.length + usage.length > textWidth) {
76	      const optParts = splitUsageParts(optionals);
77	      const getLines = (parts, indent, linePrefix) => {
78	        const lines = [];
79	        let line = [];
80	        let lineLength = (linePrefix !== null ? linePrefix.length : indent.length) - 1;
81	        for (const part of parts) {
82	          if (lineLength + 1 + part.length > textWidth && line.length > 0) {
83	            lines.push(indent + line.join(' '));
84	            line = [];
85	            lineLength = indent.length - 1;
86	          }
87	          line.push(part);
88	          lineLength += 1 + part.length;
89	        }
90	        if (line.length > 0) lines.push(indent + line.join(' '));
91	        if (linePrefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
92	        return lines;
93	      };
94	
95	      let lines;
96	      if (prefix.length + this.prog.length <= 0.75 * textWidth) {
97	        // Short program name: the first option group shares its line.
98	        const indent = ' '.repeat(prefix.length + this.prog.length + 1);
99	        lines = optParts.length > 0 ? getLines([this.prog, ...optParts], indent, prefix) : [this.prog];
100	      } else {
101	        // Long program name: it gets a line of its own.
102	        const indent = ' '.repeat(prefix.length);
103	        lines = [this.prog, ...getLines(optParts, indent, null)];
104	      }
105	      usage = lines.join('\n');
106	    }
107	
108	    return `${prefix}${usage}\n\n`;
109	  }
110	
111	  /** `format_help`: the usage block plus the `options:` section. */
112	  formatHelp(actions) {
113	    const invocations = actions.map(formatActionInvocation);
114	    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT_INCREMENT));
115	    const maxHelpPosition = Math.min(
116	      MAX_HELP_POSITION,
117	      Math.max(this.width - 20, INDENT_INCREMENT),
118	    );
119	    const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
120	    const actionWidth = Math.max(helpPosition - INDENT_INCREMENT - 2, 1);
121	    const helpWidth = Math.max(this.width - helpPosition, 11);
122	
123	    let text = `${this.formatUsage(actions)}options:\n`;
124	    actions.forEach((action, index) => {
125	      const invocation = invocations[index];
126	      if (!action.help) {
127	        text += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
128	        return;
129	      }
130	      const helpLines = wrapText(action.help, helpWidth);
131	      if (invocation.length <= actionWidth) {
132	        text += `${' '.repeat(INDENT_INCREMENT)}${invocation.padEnd(actionWidth)}  ${helpLines[0]}\n`;
133	      } else {
134	        text += `${' '.repeat(INDENT_INCREMENT)}${invocation}\n`;
135	        text += `${' '.repeat(helpPosition)}${helpLines[0]}\n`;
136	      }
137	      for (const line of helpLines.slice(1)) {
138	        text += `${' '.repeat(helpPosition)}${line}\n`;
139	      }
140	    });
141	
142	    // `HelpFormatter.format_help` collapses runs of blank lines and normalises
143	    // the surrounding ones.
144	    return `${text.replace(/\n\n\n+/g, '\n\n').replace(/^\n+|\n+$/g, '')}\n`;
145	  }
146	}
